package qynl.agent;
import net.fabricmc.api.ModInitializer;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents;import net.fabricmc.fabric.api.command.v2.CommandRegistrationCallback;import net.fabricmc.fabric.api.message.v1.ServerMessageEvents;import net.fabricmc.fabric.api.object.builder.v1.entity.FabricDefaultAttributeRegistry;import net.minecraft.server.MinecraftServer;import net.minecraft.entity.ai.pathing.PathAwareEntity;import org.slf4j.Logger;import org.slf4j.LoggerFactory;
public final class AgentQynlMod implements ModInitializer{
 public static final String MOD_ID="agentqynl";public static final Logger LOGGER=LoggerFactory.getLogger(MOD_ID);private static volatile MinecraftServer server;private static final QynlAutonomy AI=new QynlAutonomy();
 public void onInitialize(){FabricDefaultAttributeRegistry.register(CompanionManager.QYNL,PathAwareEntity.createMobAttributes());ServerLifecycleEvents.SERVER_STARTED.register(s->{server=s;LOGGER.info("Qynl autonomous companion online");});ServerLifecycleEvents.SERVER_STOPPING.register(s->{AI.shutdown();server=null;});ServerMessageEvents.CHAT_MESSAGE.register((m,p,params)->AI.chat(p,m.getContent().getString()));CommandRegistrationCallback.EVENT.register((d,r,e)->CompanionBridge.registerCommands(d));ServerLifecycleEvents.START_DATA_PACK_RELOAD.register((s,rm)->{});}
 public static MinecraftServer server(){return server;}public static QynlAutonomy ai(){return AI;}
}
